var featured=[0,1,17,14,25,28];
var grid=document.getElementById("proof-grid"),more=document.getElementById("proof-more"),showAll=false;
function pt(i){var r=proof[i];return lang==="ar"?{t:AR_PROOF[i][0],d:AR_PROOF[i][1],g:r.g,i:r.i}:r}
function card(i){var r=pt(i);return '<button type="button" class="pcard" data-proof="'+i+'"><span class="im"><img src="'+r.i+'" alt="'+r.t+' screenshot" loading="lazy"></span><span><small>'+r.g+"</small><b>"+r.t+"</b><span>"+r.d+"</span></span></button>"}
function drawProof(){
  var order=showAll?featured.concat(proof.map(function(_,i){return i}).filter(function(i){return featured.indexOf(i)<0})):featured;
  grid.innerHTML=order.map(card).join("");
  more.textContent=lang==="ar"?(showAll?AR.more_less:AR.more_all):(showAll?"Show fewer":"See all "+proof.length+" screenshots");
}
if(grid){drawProof();more.addEventListener("click",function(){showAll=!showAll;drawProof();if(!showAll)document.getElementById("proof").scrollIntoView()})}

var dlg=document.getElementById("zoom");
document.addEventListener("click",function(e){
  var b=e.target.closest("[data-proof]");if(!b||!dlg||!dlg.showModal)return;
  var r=pt(+b.dataset.proof),im=document.getElementById("zoom-img");
  im.src=r.i;im.alt=r.t;document.getElementById("zoom-t").textContent=r.t;document.getElementById("zoom-d").textContent=r.d;dlg.showModal();
});
if(dlg){document.getElementById("zoom-close").addEventListener("click",function(){dlg.close()});dlg.addEventListener("click",function(e){if(e.target===dlg)dlg.close()})}

/* language */
var EN={};
var tagged=[].slice.call(document.querySelectorAll("[data-i18n]"));
tagged.forEach(function(el){EN[el.dataset.i18n]=el.innerHTML});
var btn=document.getElementById("lang");
var META={en:{title:document.title},ar:{title:"هشام صلاح · ميديا باير"}};
function applyLang(l,save){
  lang=l;
  var root=document.documentElement;root.lang=l;root.dir=l==="ar"?"rtl":"ltr";
  tagged.forEach(function(el){var k=el.dataset.i18n,v=l==="ar"?AR[k]:EN[k];if(v!=null)el.innerHTML=v});
  document.title=META[l].title;
  if(btn){btn.textContent=l==="ar"?"English":"عربي";btn.setAttribute("aria-label",l==="ar"?"Switch to English":"التحويل للعربي")}
  setWa();if(grid)drawProof();
  if(save){try{localStorage.setItem("lang",l)}catch(e){}}
  if(save&&history.replaceState){history.replaceState(null,"",l==="ar"?"#ar":location.pathname+location.search)}
}
var start="en";
if(location.hash==="#ar"||/[?&]lang=ar/.test(location.search))start="ar";
else{try{var s=localStorage.getItem("lang");if(s)start=s}catch(e){}}
if(start==="ar")applyLang("ar",false);
if(btn)btn.addEventListener("click",function(){applyLang(lang==="ar"?"en":"ar",true)});

